#!/usr/bin/env bash
set -e

echo "=== 1. Terminating Lingering Subagents & Builds ==="
ps aux | grep -E 'herd-test|llama-swap|subagent|go run|go build' | grep -v grep | awk '{print $2}' | xargs -r kill -9 2>/dev/null || true

cd /home/toxic/sovereign/projects/herd

echo "=== 2. Restoring and Hardening internal/store/store.go ==="
cat << 'EOF' > internal/store/store.go
// Package store defines the data access contracts for llama-swap's persisted
// data. It holds the domain types and repository interfaces only; concrete
// backends live in subpackages such as store/sqlite. Callers depend on the
// interfaces here so a backend can be swapped or faked without touching them.
package store

import (
   "context"
   "time"
)

// Store is the root of data access. It groups one repository per kind of
// persisted data, all backed by the same underlying database, and owns that
// database's lifecycle.
type Store interface {
   // Activity returns the repository for request activity log rows.
   Activity() ActivityRepository

   // Cache returns the repository for model caching metadata.
   Cache() CacheRepository

   // IsInMemory reports whether the store is backed by an ephemeral in-memory
   // database (e.g. SQLite ":memory:") rather than on-disk storage.
   IsInMemory() bool

   // ListActivity returns a page of activity log entries matching the query.
   ListActivity(ctx context.Context, query ActivityQuery) (ActivityPage, error)

   // ActivityStats aggregates totals and speed histograms over the matching entries.
   ActivityStats(ctx context.Context, query ActivityStatsQuery) (ActivityStats, error)

   // Close releases the backing database. It is safe to call more than once.
   Close() error
}

// ActivityRepository persists and queries activity log entries.
type ActivityRepository interface {
   Insert(ctx context.Context, entry ActivityLogEntry) (ActivityLogEntry, error)
   List(ctx context.Context, query ActivityQuery) (ActivityPage, error)
   Stats(ctx context.Context, query ActivityStatsQuery) (ActivityStats, error)
   Prune(ctx context.Context, olderThan time.Duration) (int64, error)
}

// CacheRepository persists and queries model caching metadata.
type CacheRepository interface {
   Get(ctx context.Context, key string) (string, error)
   Set(ctx context.Context, key, value string) error
   Delete(ctx context.Context, key string) error
}

// TokenMetrics captures raw token counts and computed generation speed.
type TokenMetrics struct {
   PromptTokens     int     `json:"prompt_tokens"`
   CompletionTokens int     `json:"completion_tokens"`
   TotalTokens      int     `json:"total_tokens"`
   TokensPerSecond  float64 `json:"tokens_per_second"`
}

// ActivityLogEntry records one request processed by llama-swap.
type ActivityLogEntry struct {
   ID              int64             `json:"id"`
   RequestID       string            `json:"request_id"`
   Model           string            `json:"model"`
   Profile         string            `json:"profile"`
   ClientIP        string            `json:"client_ip"`
   Status          int               `json:"status"`
   DurationMs      int64             `json:"duration_ms"`
   TTFTMs          int64             `json:"ttft_ms"`
   Tokens          TokenMetrics      `json:"tokens"`
   Streamed        bool              `json:"streamed"`
   PromptSummary   string            `json:"prompt_summary"`
   ResponseSummary string            `json:"response_summary"`
   Error           string            `json:"error"`
   Metadata        map[string]string `json:"metadata"`
   Timestamp       time.Time         `json:"timestamp"`
}

// ActivityFilter holds optional predicates for filtering activity log entries.
type ActivityFilter struct {
   Model     string
   Profile   string
   ClientIP  string
   Status    int
   Streamed  *bool
   HasError  *bool
   Search    string
   StartTime *time.Time
   EndTime   *time.Time
}

// ActivityQuery defines pagination, sorting, and filtering for List.
type ActivityQuery struct {
   ActivityFilter
   Limit int
   Page  int
   Sort  string
   Order string
}

// ActivityPage is the paginated result from ActivityRepository.List.
type ActivityPage struct {
   Entries    []ActivityLogEntry `json:"entries"`
   Total      int                `json:"total"`
   Page       int                `json:"page"`
   Limit      int                `json:"limit"`
   TotalPages int                `json:"total_pages"`
}

// ActivityStatsQuery defines aggregation parameters.
type ActivityStatsQuery struct {
   Model     string
   StartTime *time.Time
   EndTime   *time.Time
}

// HistogramData captures statistical distribution of speeds.
type HistogramData struct {
   Min    float64 `json:"min"`
   Max    float64 `json:"max"`
   Avg    float64 `json:"avg"`
   Median float64 `json:"median"`
   P95    float64 `json:"p95"`
   P99    float64 `json:"p99"`
}

// ActivityStats holds aggregate totals and throughput metrics.
type ActivityStats struct {
   TotalRequests int                      `json:"total_requests"`
   TotalTokens   int                      `json:"total_tokens"`
   AverageTTFT   float64                  `json:"average_ttft_ms"`
   Speed         HistogramData            `json:"speed_tokens_sec"`
   ByModel       map[string]ActivityStats `json:"by_model,omitempty"`
}

var activitySortColumns = map[string]string{
   "id":          "id",
   "timestamp":   "timestamp",
   "duration":    "duration_ms",
   "model":       "model",
   "tokens":      "tokens_total",
   "speed":       "tokens_per_second",
}

// ActivitySortColumn returns the SQL column name for an API key.
func ActivitySortColumn(key string) (string, bool) {
   col, ok := activitySortColumns[key]
   return col, ok
}
EOF

echo "=== 3. Implementing Store Delegations in internal/store/sqlite/sqlite.go ==="
python3 -c '
from pathlib import Path

p = Path("internal/store/sqlite/sqlite.go")
content = p.read_text()

# Strip any existing broken delegations at EOF
if "func (s *Store) ListActivity" in content:
    content = content[:content.find("func (s *Store) ListActivity")].rstrip() + "\n"

delegations = """
// ListActivity implements store.Store directly on sqlite.Store.
func (s *Store) ListActivity(ctx context.Context, query store.ActivityQuery) (store.ActivityPage, error) {
   if s == nil || s.activity == nil {
      return store.ActivityPage{}, nil
   }
   return s.activity.List(ctx, query)
}

// ActivityStats implements store.Store directly on sqlite.Store.
func (s *Store) ActivityStats(ctx context.Context, query store.ActivityStatsQuery) (store.ActivityStats, error) {
   if s == nil || s.activity == nil {
      return store.ActivityStats{}, nil
   }
   return s.activity.Stats(ctx, query)
}
"""

if "func (s *Store) ListActivity" not in content:
    content = content + "\n" + delegations

p.write_text(content)
'

echo "=== 4. Enforcing Value Interfaces in Server and Metrics ==="
sed -i 's/\*store\.Store/store\.Store/g' internal/server/server.go
sed -i 's/\*store\.Store/store\.Store/g' internal/server/metrics.go

echo "=== 5. Fixing Server Test Stubs & Imports ==="
python3 -c '
from pathlib import Path

st_path = Path("internal/server/server_test.go")
st_code = st_path.read_text()

if "\"github.com/mostlygeek/llama-swap/internal/store/sqlite\"" not in st_code:
    st_code = st_code.replace(
        "\"github.com/mostlygeek/llama-swap/internal/store\"",
        "\"github.com/mostlygeek/llama-swap/internal/store\"\n\t\"github.com/mostlygeek/llama-swap/internal/store/sqlite\""
    )

st_code = st_code.replace("st, err := store.New(\"\")", "st, err := sqlite.New(\"\")")

if "func newTestServerWithConfig(" not in st_code:
    stub = """
func newTestServerWithConfig(cfg config.Config, local router.LocalRouter, peer router.Router) *Server {
   s := newTestServer(local, peer)
   s.cfg = cfg
   return s
}
"""
    st_code = st_code + "\n" + stub

st_path.write_text(st_code)

cors_path = Path("internal/server/cors_test.go")
if cors_path.exists():
    cors_code = cors_path.read_text()
    cors_code = cors_code.replace(
        "return newTestServerWithConfig(\n\t\tconfig.Config{Security: &config.SecurityConfig{CORS: cfg}},\n\t\tnewStubRouter([]string{\"m1\"}, \"OK\"),\n\t)",
        "return newTestServerWithConfig(\n\t\tconfig.Config{Security: &config.SecurityConfig{CORS: cfg}},\n\t\tnewStubRouter([]string{\"m1\"}, \"OK\"),\n\t\tnewStubRouter(nil, \"\"),\n\t)"
    )
    cors_path.write_text(cors_code)

sse_path = Path("internal/server/models_sse_comprehensive_test.go")
if sse_path.exists():
    sse_code = sse_path.read_text()
    if "\"github.com/mostlygeek/llama-swap/internal/store/sqlite\"" not in sse_code:
        sse_code = sse_code.replace(
            "\"github.com/mostlygeek/llama-swap/internal/store\"",
            "\"github.com/mostlygeek/llama-swap/internal/store\"\n\t\"github.com/mostlygeek/llama-swap/internal/store/sqlite\""
        )
    sse_code = sse_code.replace("store.New(", "sqlite.New(")
    sse_path.write_text(sse_code)
'

echo "=== 6. Rebuilding Herd Binary & Running Unit Tests ==="
go build -o /tmp/herd-test .
echo "SUCCESS: Binary /tmp/herd-test compiled cleanly."

go test -run 'TestServer|TestStore' ./internal/server/... ./internal/store/...
echo "SUCCESS: Store & Server tests verified."

