// TestServer_CORSDeclaredBlockDoesNotWidenToWildcard guards the point of the
// two-mode model: a declared block never falls back to allowing any origin.
func TestServer_CORSDeclaredBlockDoesNotWidenToWildcard(t *testing.T) {
	s := corsTestServer(t, config.CORSConfig{
		AllowedOrigins: []string{"https://dash.example.com"},
	})

	for _, origin := range []string{"https://evil.example.com", "http://localhost:5173", "null"} {
		req := httptest.NewRequest(http.MethodGet, "/running", nil)
		req.Header.Set("Origin", origin)
		w := httptest.NewRecorder()
		s.ServeHTTP(w, req)
		assertNoCORSHeaders(t, w, "unlisted origin "+origin)
	}
}

// pnaTestConfig is a policy with Private Network Access turned on, which
// requires explicit origins.
func pnaTestConfig() config.CORSConfig {
	return config.CORSConfig{
		AllowedOrigins:      []string{"https://dash.example.com"},
		AllowPrivateNetwork: true,
	}
}

// pnaPreflight builds a Chrome-style Private Network Access preflight.
func pnaPreflight(origin string, ask bool) *http.Request {
	req := httptest.NewRequest(http.MethodOptions, "/v1/chat/completions", nil)
	req.Header.Set("Origin", origin)
	req.Header.Set("Access-Control-Request-Method", "POST")
	if ask {
		req.Header.Set("Access-Control-Request-Private-Network", "true")
	}
	return req
}

func TestServer_CORSPrivateNetworkPreflight(t *testing.T) {
	s := corsTestServer(t, pnaTestConfig())

	w := httptest.NewRecorder()
	s.ServeHTTP(w, pnaPreflight("https://dash.example.com", true))

	if w.Code != http.StatusNoContent {
		t.Fatalf("status=%d want 204", w.Code)
	}
	if got := w.Header().Get("Access-Control-Allow-Private-Network"); got != "true" {
		t.Errorf("Access-Control-Allow-Private-Network=%q want true", got)
	}
	if got := w.Header().Get("Vary"); !strings.Contains(got, "Access-Control-Request-Private-Network") {
		t.Errorf("Vary=%q want it to contain Access-Control-Request-Private-Network", got)
	}
}

// TestServer_CORSPrivateNetworkOnlyWhenRequested keeps the header off an
// ordinary preflight, so it is never sent to a browser that did not ask.
func TestServer_CORSPrivateNetworkOnlyWhenRequested(t *testing.T) {
	s := corsTestServer(t, pnaTestConfig())

	w := httptest.NewRecorder()
	s.ServeHTTP(w, pnaPreflight("https://dash.example.com", false))

	if _, ok := w.Header()["Access-Control-Allow-Private-Network"]; ok {
		t.Error("Access-Control-Allow-Private-Network sent on a preflight that did not request it")
	}
}

// TestServer_CORSPrivateNetworkOffByDefault is the backwards-compatibility
// guard: llama-swap never sent this header, so a config that does not ask for
// it must not start, even when a browser requests it.
func TestServer_CORSPrivateNetworkOffByDefault(t *testing.T) {
	configs := map[string]config.CORSConfig{
		"legacy permissive policy": {},
		"origins but no opt-in":    {AllowedOrigins: []string{"https://dash.example.com"}},
	}

	for name, cfg := range configs {
		t.Run(name, func(t *testing.T) {
			s := corsTestServer(t, cfg)
			w := httptest.NewRecorder()
			s.ServeHTTP(w, pnaPreflight("https://dash.example.com", true))

			if _, ok := w.Header()["Access-Control-Allow-Private-Network"]; ok {
				t.Error("Access-Control-Allow-Private-Network sent without being configured")
			}
		})
	}
}

// TestServer_CORSPrivateNetworkNotOnActualResponse covers the header being
// preflight-only: it has no meaning on a real response.
func TestServer_CORSPrivateNetworkNotOnActualResponse(t *testing.T) {
	s := corsTestServer(t, pnaTestConfig())

	req := httptest.NewRequest(http.MethodGet, "/running", nil)
	req.Header.Set("Origin", "https://dash.example.com")
	req.Header.Set("Access-Control-Request-Private-Network", "true")
	w := httptest.NewRecorder()
	s.ServeHTTP(w, req)

	if _, ok := w.Header()["Access-Control-Allow-Private-Network"]; ok {
		t.Error("Access-Control-Allow-Private-Network sent on a non-preflight response")
	}
}

func TestServer_CORSPrivateNetworkDisallowedOrigin(t *testing.T) {
	s := corsTestServer(t, pnaTestConfig())

	w := httptest.NewRecorder()
	s.ServeHTTP(w, pnaPreflight("https://evil.example.com", true))

	assertNoCORSHeaders(t, w, "PNA preflight from an unlisted origin")
}

// TestServer_CORSPrivateNetworkNeverWithWildcardOrigin pins the invariant that
// private-network access is never granted alongside a wildcard origin, whether
// the wildcard came from the legacy fallback or was written out. Config
// validation rejects both of these, so this exercises newCORSPolicy directly:
// the guarantee has to survive without the validator in front of it.
func TestServer_CORSPrivateNetworkNeverWithWildcardOrigin(t *testing.T) {
	configs := map[string]config.CORSConfig{
		"legacy fallback to wildcard": {AllowPrivateNetwork: true},
		"explicit wildcard": {
			AllowedOrigins:      []string{"*"},
			AllowPrivateNetwork: true,
		},
	}

	for name, cfg := range configs {
		t.Run(name, func(t *testing.T) {
			if newCORSPolicy(cfg).allowPrivateNetwork {
				t.Error("allowPrivateNetwork survived alongside a wildcard origin")
			}
		})
	}
}

// TestServer_CORSOriginMatchIsHostCaseInsensitive covers a config that spells
// the host in different case than the browser does. The match must ignore
// case, and the answer must be the request's spelling: a browser compares
// Access-Control-Allow-Origin against its own origin, which it serializes with
// the host lowercased, so replying with the config's mixed-case spelling would
// fail that check on an origin that is in fact allowed.
func TestServer_CORSOriginMatchIsHostCaseInsensitive(t *testing.T) {
	s := corsTestServer(t, config.CORSConfig{
		AllowedOrigins: []string{"https://Dash.Example.com"},
	})

	const origin = "https://dash.example.com"
	req := httptest.NewRequest(http.MethodGet, "/running", nil)
	req.Header.Set("Origin", origin)
	w := httptest.NewRecorder()
	s.ServeHTTP(w, req)

	if got := w.Header().Get("Access-Control-Allow-Origin"); got != origin {
		t.Errorf("Access-Control-Allow-Origin=%q want %q, the origin the request sent", got, origin)
	}
}

// TestServer_CORSNullOriginNotAllowedByList checks that the sandboxed-document
// "null" origin does not match a configured list.
func TestServer_CORSNullOriginNotAllowedByList(t *testing.T) {
	s := corsTestServer(t, config.CORSConfig{
		AllowedOrigins: []string{"https://dash.example.com"},
	})

	req := httptest.NewRequest(http.MethodGet, "/running", nil)
	req.Header.Set("Origin", "null")
	w := httptest.NewRecorder()
	s.ServeHTTP(w, req)

	assertNoCORSHeaders(t, w, `Origin: null`)
}

func TestServer_SanitizeAccessControlRequestHeaders(t *testing.T) {
	cases := []struct {
		in   string
		want string
	}{
		{"Content-Type, Authorization", "Content-Type, Authorization"},
		{"  X-Custom ,  Accept ", "X-Custom, Accept"},
		{"Valid, Bad Header", "Valid"},
		{"Bad@Header", ""},
		{"", ""},
		{",,,", ""},
		{"X-A,,X-B", "X-A, X-B"},
		{"X-A,", "X-A"},
		{"\tX-Tabbed\t", "X-Tabbed"},
	}
	for _, c := range cases {
		if got := sanitizeAccessControlRequestHeaderValues(c.in); got != c.want {
			t.Errorf("sanitize(%q) = %q, want %q", c.in, got, c.want)
		}
	}
}

package sqlite

import (
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
	"strings"
	"time"

	"github.com/mostlygeek/llama-swap/internal/store"
)

// activityRepository implements store.ActivityRepository over the activity
// table.
type activityRepository struct {
	db *sql.DB
}

var _ store.ActivityRepository = (*activityRepository)(nil)

// activitySortColumns maps the store's sortable keys onto SQL columns. Only
// these column names ever reach a query; TestActivity_SortColumnsCoverStoreKeys
// checks the map stays in step with store.ActivitySortKeys.
var activitySortColumns = map[string]string{
	"id":                "id",
	"time":              "ts_created",
	"model":             "model_id",
	"src":               "src",
	"req_path":          "req_path",
	"resp_status_code":  "resp_status_code",
	"resp_content_type": "resp_content_type",
	"cached":            "cache_tokens",
	"prompt":            "input_tokens",
	"generated":         "output_tokens",
	"drafted":           "draft_tokens",
	"prompt_speed":      "prompt_per_second",
	"gen_speed":         "tokens_per_second",
	"duration":          "duration_ms",
}

func (r *activityRepository) Insert(ctx context.Context, entry store.ActivityLogEntry) (store.ActivityLogEntry, error) {
	if entry.Timestamp.IsZero() {
		entry.Timestamp = time.Now()
	}
	metadataJSON, err := marshalMetadata(entry.Metadata)
	if err != nil {
		return store.ActivityLogEntry{}, err
	}

	res, err := r.db.ExecContext(ctx, `
		INSERT INTO activity (
			ts_created, src, model_id, req_path, resp_content_type, resp_status_code,
			cache_tokens, draft_tokens, draft_acc_tokens, input_tokens, output_tokens,
			prompt_per_second, tokens_per_second, duration_ms, error_msg, metadata_json
		) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
		entry.Timestamp.Unix(),
		entry.Src,
		entry.Model,
		entry.ReqPath,
		entry.RespContentType,
		entry.RespStatusCode,
		entry.Tokens.CachedTokens,
		entry.Tokens.DraftTokens,
		entry.Tokens.DraftAccTokens,
		entry.Tokens.InputTokens,
		entry.Tokens.OutputTokens,
		entry.Tokens.PromptPerSecond,
		entry.Tokens.TokensPerSecond,
		entry.DurationMs,
		entry.ErrorMsg,
		metadataJSON,
	)
	if err != nil {
		return store.ActivityLogEntry{}, fmt.Errorf("insert activity: %w", err)
	}
	id, err := res.LastInsertId()
	if err != nil {
		return store.ActivityLogEntry{}, fmt.Errorf("insert activity id: %w", err)
	}
	entry.ID = int(id)
	return entry, nil
}


// ValidActivitySortKey reports whether key is accepted by ActivityQuery.Sort.
func (r *activityRepository) ValidActivitySortKey(key string) bool {
	if _, ok := activitySortColumns[key]; !ok {
		return false
	}
	return true
}
func (r *activityRepository) List(ctx context.Context, query store.ActivityQuery) (store.ActivityPage, error) {
	query = query.WithDefaults()
	offset := (query.Page - 1) * query.Limit

	where, args := activityWhere(query.ActivityFilter)
	var total int
	if err := r.db.QueryRowContext(ctx, `SELECT COUNT(*) FROM activity`+where, args...).Scan(&total); err != nil {
		return store.ActivityPage{}, fmt.Errorf("count activity: %w", err)
	}

	rows, err := r.db.QueryContext(ctx, `
		SELECT
			id, ts_created, src, model_id, req_path, resp_content_type, resp_status_code,
			cache_tokens, draft_tokens, draft_acc_tokens, input_tokens, output_tokens,
			prompt_per_second, tokens_per_second, duration_ms, error_msg, metadata_json
		FROM activity`+where+activityOrderBy(query)+`
		LIMIT ? OFFSET ?`,
		append(args, query.Limit, offset)...,
	)
	if err != nil {
		return store.ActivityPage{}, fmt.Errorf("list activity: %w", err)
	}
	defer rows.Close()

	entries := []store.ActivityLogEntry{}
	for rows.Next() {
		entry, err := scanActivity(rows)
		if err != nil {
			return store.ActivityPage{}, err
		}
		entries = append(entries, entry)
	}
	if err := rows.Err(); err != nil {
		return store.ActivityPage{}, fmt.Errorf("list activity rows: %w", err)
	}

	return store.ActivityPage{
		Data:       entries,
		Page:       query.Page,
		Limit:      query.Limit,
		Total:      total,
		TotalPages: store.TotalPages(total, query.Limit),
	}, nil
}

func (r *activityRepository) Stats(ctx context.Context, query store.ActivityStatsQuery) (store.ActivityStats, error) {
	filter := store.ActivityFilter{}
	if model := strings.TrimSpace(query.Model); model != "" {
		filter.Models = []string{model}
	}
	where, args := activityWhere(filter)
	row := r.db.QueryRowContext(ctx, `
		SELECT
			COALESCE(MAX(id), 0),
			COALESCE(SUM(input_tokens), 0),
			COALESCE(SUM(output_tokens), 0),
			COALESCE(SUM(CASE WHEN cache_tokens > 0 THEN cache_tokens ELSE 0 END), 0)
		FROM activity`+where, args...)

	var stats store.ActivityStats
	if err := row.Scan(&stats.TotalRequests, &stats.TotalInputTokens, &stats.TotalOutputTokens, &stats.TotalCacheTokens); err != nil {
		return store.ActivityStats{}, fmt.Errorf("activity stats: %w", err)
	}

	promptValues, genValues, err := r.speedValues(ctx, where, args)
	if err != nil {
		return store.ActivityStats{}, err
	}
	stats.PromptHistogram = store.NewHistogram(promptValues)
	stats.GenerationHistogram = store.NewHistogram(genValues)
	return stats, nil
}

// speedValues reads both histogram source columns in a single scan. Zero
// values mean the speed was not reported and are excluded per column. No
// ORDER BY: store.NewHistogram sorts the values itself.
func (r *activityRepository) speedValues(ctx context.Context, where string, args []any) (prompt, gen []float64, err error) {
	filter := where
	if filter == "" {
		filter = ` WHERE prompt_per_second > 0 OR tokens_per_second > 0`
	} else {
		filter += ` AND (prompt_per_second > 0 OR tokens_per_second > 0)`
	}
	rows, err := r.db.QueryContext(ctx,
		`SELECT prompt_per_second, tokens_per_second FROM activity`+filter, args...)
	if err != nil {
		return nil, nil, fmt.Errorf("activity histogram: %w", err)
	}
	defer rows.Close()

	for rows.Next() {
		var promptValue, genValue float64
		if err := rows.Scan(&promptValue, &genValue); err != nil {
			return nil, nil, fmt.Errorf("activity histogram row: %w", err)
		}
		if promptValue > 0 {
			prompt = append(prompt, promptValue)
		}
		if genValue > 0 {
			gen = append(gen, genValue)
		}
	}
	return prompt, gen, rows.Err()
}

func (r *activityRepository) Prune(ctx context.Context, maxRows int) error {
	if maxRows <= 0 {
		return nil
	}
	// AUTOINCREMENT ids are monotonic and never reused, so the rows beyond
	// the newest maxRows are exactly those with id <= MAX(id) - maxRows.
	// One statement keeps the per-insert prune cheap; if ids ever become
	// sparse this retains fewer than maxRows rows, which is fine for a
	// bounded recent-activity cap.
	if _, err := r.db.ExecContext(ctx,
		`DELETE FROM activity WHERE id <= (SELECT MAX(id) FROM activity) - ?`, maxRows,
	); err != nil {
		return fmt.Errorf("prune activity: %w", err)
	}
	return nil
}

// activityOrderBy builds a safe ORDER BY clause from the query's sort key and
// direction. Unknown sort keys fall back to "id". A secondary "id" sort keeps
// pagination stable when the primary column has duplicate values.
func activityOrderBy(query store.ActivityQuery) string {
	column, ok := activitySortColumns[query.Sort]
	if !ok {
		column = "id"
	}
	direction := "DESC"
	if strings.EqualFold(query.Order, "asc") {
		direction = "ASC"
	}
	if column == "id" {
		return " ORDER BY id " + direction
	}
	return " ORDER BY " + column + " " + direction + ", id " + direction
}

// activityWhere builds a parameterized WHERE clause from a filter. It returns
// an empty string when nothing is filtered. Callers append further conditions
// with " AND ...", so the clause is always a single unparenthesized conjunction.
func activityWhere(filter store.ActivityFilter) (string, []any) {
	var conditions []string
	var args []any

	models := make([]string, 0, len(filter.Models))
	for _, model := range filter.Models {
		if model = strings.TrimSpace(model); model != "" {
			models = append(models, model)
		}
	}
	if len(models) > 0 {
		placeholders := strings.TrimSuffix(strings.Repeat("?, ", len(models)), ", ")
		conditions = append(conditions, "model_id IN ("+placeholders+")")
		for _, model := range models {
			args = append(args, model)
		}
	}

	if !filter.Start.IsZero() {
		conditions = append(conditions, "ts_created >= ?")
		args = append(args, filter.Start.Unix())
	}
	if !filter.End.IsZero() {
		conditions = append(conditions, "ts_created <= ?")
		args = append(args, filter.End.Unix())
	}
	if filter.MinID > 0 {
		conditions = append(conditions, "id >= ?")
		args = append(args, filter.MinID)
	}
	if filter.MaxID > 0 {
		conditions = append(conditions, "id <= ?")
		args = append(args, filter.MaxID)
	}
	if filter.SrcPrefix != "" {
		// A bounded lexical range is a literal prefix match (SQL wildcard
		// characters remain data) and can use idx_activity_src_created_id.
		conditions = append(conditions, "src >= ? AND src < ?")
		args = append(args, filter.SrcPrefix, filter.SrcPrefix+"\U0010FFFF")
	}

	if len(conditions) == 0 {
		return "", nil
	}
	return " WHERE " + strings.Join(conditions, " AND "), args
}

func marshalMetadata(metadata map[string]string) (string, error) {
	if len(metadata) == 0 {
		return "", nil
	}
	data, err := json.Marshal(metadata)
	if err != nil {
		return "", fmt.Errorf("marshal activity metadata: %w", err)
	}
	return string(data), nil
}

type activityScanner interface {
	Scan(dest ...any) error
}

func scanActivity(scanner activityScanner) (store.ActivityLogEntry, error) {
	var entry store.ActivityLogEntry
	var ts int64
	var metadataJSON string
	if err := scanner.Scan(
		&entry.ID,
		&ts,
		&entry.Src,
		&entry.Model,
		&entry.ReqPath,
		&entry.RespContentType,
		&entry.RespStatusCode,
		&entry.Tokens.CachedTokens,
		&entry.Tokens.DraftTokens,
		&entry.Tokens.DraftAccTokens,
		&entry.Tokens.InputTokens,
		&entry.Tokens.OutputTokens,
		&entry.Tokens.PromptPerSecond,
		&entry.Tokens.TokensPerSecond,
		&entry.DurationMs,
		&entry.ErrorMsg,
		&metadataJSON,
	); err != nil {
		return store.ActivityLogEntry{}, fmt.Errorf("scan activity: %w", err)
	}
	entry.Timestamp = time.Unix(ts, 0)
	if metadataJSON != "" {
		if err := json.Unmarshal([]byte(metadataJSON), &entry.Metadata); err != nil {
			return store.ActivityLogEntry{}, fmt.Errorf("unmarshal activity metadata: %w", err)
		}
	}
	return entry, nil
}

package sqlite

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"time"

	"github.com/mostlygeek/llama-swap/internal/store"
)

// cacheRepository implements store.CacheRepository over the cache table.
//
// Expiry is evaluated in SQL as ts_created + ttl_seconds < now so a read and
// its expiry check are one round trip. Rows with ttl_seconds <= 0 never
// expire.
type cacheRepository struct {
	db *sql.DB
}

var _ store.CacheRepository = (*cacheRepository)(nil)

// beforeExpiryDelete runs between reading a row that turned out to be expired
// and deleting it. It is nil outside tests, and exists so the interleaving the
// conditional delete guards against can be produced on demand rather than
// waited for: the gap between those two statements is a few instructions wide
// and a concurrent writer almost never lands in it by chance.
var beforeExpiryDelete func()

func (r *cacheRepository) Get(ctx context.Context, key string) (store.CacheEntry, bool, error) {
	var (
		data []byte
		ttl  int64
		ts   int64
	)
	err := r.db.QueryRowContext(ctx, `
		SELECT data, ttl_seconds, ts_created FROM cache WHERE key = ?`,
		key,
	).Scan(&data, &ttl, &ts)
	if errors.Is(err, sql.ErrNoRows) {
		return store.CacheEntry{}, false, nil
	}
	if err != nil {
		return store.CacheEntry{}, false, fmt.Errorf("get cache: %w", err)
	}

	now := time.Now()
	entry := store.CacheEntry{
		Key:       key,
		Data:      data,
		TTL:       time.Duration(ttl) * time.Second,
		Timestamp: time.Unix(ts, 0),
	}
	if entry.Expired(now) {
		if beforeExpiryDelete != nil {
			beforeExpiryDelete()
		}
		// Drop it now so a key that is never written again does not linger
		// until the next Prune.
		//
		// The delete repeats the expiry test in SQL against the same clock
		// rather than deleting by key. The read above and this write are
		// separate statements, so a Set can land between them, and a
		// just-written row is never expired against this now: the condition
		// makes the cleanup a no-op instead of discarding it.
		if _, err := r.db.ExecContext(ctx, `
			DELETE FROM cache
			WHERE key = ? AND ttl_seconds > 0 AND ts_created + ttl_seconds < ?`,
			key, now.Unix(),
		); err != nil {
			return store.CacheEntry{}, false, fmt.Errorf("delete expired cache: %w", err)
		}
		return store.CacheEntry{}, false, nil
	}
	return entry, true, nil
}

func (r *cacheRepository) Set(ctx context.Context, entry store.CacheEntry) error {
	if entry.Timestamp.IsZero() {
		entry.Timestamp = time.Now()
	}
	// ttl_seconds is whole seconds, and 0 means "never expires". Rounding a
	// positive TTL down would turn anything under a second into a permanent
	// row, so round up instead: a positive TTL always expires.
	ttl := int64(0)
	if entry.TTL > 0 {
		ttl = int64((entry.TTL + time.Second - 1) / time.Second)
	}
	_, err := r.db.ExecContext(ctx, `
		INSERT INTO cache (key, data, ttl_seconds, ts_created)
		VALUES (?, ?, ?, ?)
		ON CONFLICT(key) DO UPDATE SET
			data = excluded.data,
			ttl_seconds = excluded.ttl_seconds,
			ts_created = excluded.ts_created`,
		entry.Key, entry.Data, ttl, entry.Timestamp.Unix(),
	)
	if err != nil {
		return fmt.Errorf("set cache: %w", err)
	}
	return nil
}

func (r *cacheRepository) Delete(ctx context.Context, key string) error {
	if _, err := r.db.ExecContext(ctx, `DELETE FROM cache WHERE key = ?`, key); err != nil {
		return fmt.Errorf("delete cache: %w", err)
	}
	return nil
}

func (r *cacheRepository) Prune(ctx context.Context) error {
	_, err := r.db.ExecContext(ctx, `
		DELETE FROM cache
		WHERE ttl_seconds > 0 AND ts_created + ttl_seconds < ?`,
		time.Now().Unix(),
	)
	if err != nil {
		return fmt.Errorf("prune cache: %w", err)
	}
	return nil
}

package store

import (
	"context"
	"path/filepath"
	"testing"
	"time"
)

func TestStore_InsertListAndFilterActivity(t *testing.T) {
	ctx := context.Background()
	store, err := New("")
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	defer store.Close()

	for i, model := range []string{"m1", "m2", "m1"} {
		_, err := store.InsertActivity(ctx, ActivityLogEntry{
			Timestamp: time.Unix(int64(100+i), 0),
			Model:     model,
			ReqPath:   "/v1/chat/completions",
			Tokens: TokenMetrics{
				InputTokens:     i + 1,
				OutputTokens:    i + 2,
				PromptPerSecond: float64(10 + i),
				TokensPerSecond: float64(20 + i),
			},
			Metadata: map[string]string{"trace": model},
		})
		if err != nil {
			t.Fatalf("InsertActivity: %v", err)
		}
	}

	page, err := store.ListActivity(ctx, ActivityQuery{Limit: 2, Page: 1})
	if err != nil {
		t.Fatalf("ListActivity: %v", err)
	}
	if page.Total != 3 || page.TotalPages != 2 || len(page.Data) != 2 {
		t.Fatalf("page = %+v", page)
	}
	if page.Data[0].ID <= page.Data[1].ID {
		t.Fatalf("activity is not newest first: %+v", page.Data)
	}
	if page.Data[0].Metadata["trace"] != "m1" {
		t.Fatalf("metadata = %+v", page.Data[0].Metadata)
	}

	filtered, err := store.ListActivity(ctx, ActivityQuery{
		ActivityFilter: ActivityFilter{Models: []string{"m1"}},
		Limit:          10,
		Page:           1,
	})
	if err != nil {
		t.Fatalf("ListActivity filtered: %v", err)
	}
	if filtered.Total != 2 || len(filtered.Data) != 2 {
		t.Fatalf("filtered page = %+v", filtered)
	}
	for _, entry := range filtered.Data {
		if entry.Model != "m1" {
			t.Fatalf("filtered model = %q", entry.Model)
		}
	}
}

// seedFilterActivity inserts 5 rows with ids 1..5 at ts_created 1000..1004,
// alternating models m1/m2/m1/m2/m1, and returns the store.
func seedFilterActivity(t *testing.T) (*Store, context.Context) {
	t.Helper()
	ctx := context.Background()
	store, err := New("")
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	t.Cleanup(func() { store.Close() })

	for i, model := range []string{"m1", "m2", "m1", "m2", "m1"} {
		if _, err := store.InsertActivity(ctx, ActivityLogEntry{
			Timestamp: time.Unix(int64(1000+i), 0),
			Model:     model,
		}); err != nil {
			t.Fatalf("InsertActivity: %v", err)
		}
	}
	return store, ctx
}

// entryIDs returns the ids of a page in the order they were returned.
func entryIDs(entries []ActivityLogEntry) []int {
	ids := make([]int, len(entries))
	for i, entry := range entries {
		ids[i] = entry.ID
	}
	return ids
}

func equalIDs(got, want []int) bool {
	if len(got) != len(want) {
		return false
	}
	for i := range got {
		if got[i] != want[i] {
			return false
		}
	}
	return true
}

func TestStore_ListActivityFilterTimeRange(t *testing.T) {
	store, ctx := seedFilterActivity(t)

	tests := []struct {
		name   string
		filter ActivityFilter
		want   []int
	}{
		{"start only", ActivityFilter{Start: time.Unix(1002, 0)}, []int{5, 4, 3}},
		{"end only", ActivityFilter{End: time.Unix(1001, 0)}, []int{2, 1}},
		{"both bounds inclusive", ActivityFilter{Start: time.Unix(1001, 0), End: time.Unix(1003, 0)}, []int{4, 3, 2}},
		{"empty range", ActivityFilter{Start: time.Unix(9000, 0)}, []int{}},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			page, err := store.ListActivity(ctx, ActivityQuery{ActivityFilter: tt.filter, Limit: 10, Page: 1})
			if err != nil {
				t.Fatalf("ListActivity: %v", err)
			}
			if got := entryIDs(page.Data); !equalIDs(got, tt.want) {
				t.Fatalf("ids = %v, want %v", got, tt.want)
			}
			if page.Total != len(tt.want) {
				t.Fatalf("Total = %d, want %d", page.Total, len(tt.want))
			}
		})
	}
}

