			MinID:  2,
			MaxID:  5,
		},
		Limit: 1,
		Page:  1,
	})
	if err != nil {
		t.Fatalf("ListActivity: %v", err)
	}
	// m1 rows are ids 1,3,5; the time and id bounds each drop id 1, leaving
	// 3 and 5.
	if page.Total != 2 || page.TotalPages != 2 {
		t.Fatalf("Total = %d, TotalPages = %d, want 2 and 2", page.Total, page.TotalPages)
