from pathlib import Path

p = Path("internal/store/sqlite/sqlite.go")
content = p.read_text()

# Fix the broken comment
content = content.replace(
    "// ListActivity implements store.Store.\n\n\n",
    ""
)

# Remove any existing delegations at EOF
for method_name in ["ListActivity", "ActivityStats", "InsertActivity", "PruneActivity"]:
