        content = content[:content.find(f"func (s *Store) {method_name}")].rstrip() + "\n"

delegations = """
// ListActivity implements store.Store directly on sqlite.Store.
func (s *Store) ListActivity(ctx context.Context, query store.ActivityQuery) (store.ActivityPage, error) {
	if s == nil || s.activity == nil {
		return store.ActivityPage{}, nil
	}
	return s.activity.List(ctx, query)
}

// ActivityStats implements store.Store directly on sqlite.Store.
func (s *Store) ActivityStats(ctx context.Context, query store.ActivityStatsQuery) (store.ActivityStats, error) {
	if s == nil || s.activity == nil {
		return store.ActivityStats{}, nil
	}
	return s.activity.Stats(ctx, query)
}

// InsertActivity implements store.Store directly on sqlite.Store.
func (s *Store) InsertActivity(ctx context.Context, entry store.ActivityLogEntry) (store.ActivityLogEntry, error) {
	if s == nil || s.activity == nil {
		return store.ActivityLogEntry{}, nil
	}
	return s.activity.Insert(ctx, entry)
}

// PruneActivity implements store.Store directly on sqlite.Store.
func (s *Store) PruneActivity(ctx context.Context, maxRows int) error {
	if s == nil || s.activity == nil {
		return nil
	}
	return s.activity.Prune(ctx, maxRows)
}
"""

if "func (s *Store) ListActivity" not in content:
    content = content.rstrip() + "\n" + delegations
else:
    # Append delegations that weren't already there
    existing_methods = set()
    for m in ["ListActivity", "ActivityStats", "InsertActivity", "PruneActivity"]:
        if f"func (s *Store) {m}" in content:
            existing_methods.add(m)
    new_decls = []
    for m in ["ListActivity", "ActivityStats", "InsertActivity", "PruneActivity"]:
        if m not in existing_methods:
            new_decls.append(f"// {m} implements store.Store directly on sqlite.Store.\nfunc (s *Store) {m}")

p.write_text(content)
PYEOF

echo "=== 3. Fixing remaining broken comment if present ==="
# Clean up any double-blank-lines or broken comments
sed -i '/^\/\/ ListActivity implements store\.Store\.$/{N;/\n\n\n/d}' internal/store/sqlite/sqlite.go

echo "=== 4. Verifying build ==="
go build -o /tmp/herd-test . 2>&1
echo "SUCCESS: Binary compiled cleanly."
